import{_ as l,c as n,j as t,o as a}from"./chunks/framework.CqbvlPrP.js";const i=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易像融资.md","filePath":"stock/交易认知/交易像融资.md"}'),o={name:"stock/交易认知/交易像融资.md"};function s(r,e,p,c,_,d){return a(),n("div",null,e[0]||(e[0]=[t("p",null,"入场点不重要，或者没那么重要。所有的趋势跟踪方法，入场点不管是形态跟踪，还是均线交叉，本质上都是他涨了一段距离，或者跌了一段距离，你进场了，出厂方式总结起来无非是回调了多少，你出场了。",-1),t("p",null,"盈利核心的秘密，是在某一次进场的时候，他刚好有较长的惯性，你的系统跟踪了这个惯性，所以你赚一次的钱足够涵盖你多次的损失。",-1),t("p",null,"其实交易系统有点类似于，你是在天使轮投资，A，B轮，还是二级市场，或者你也可以对冲（投资两个负相关的板块），天使轮回报大，但10死1生，越往后，趋势越明显的时候进入，你的回报自然就越小。",-1),t("p",null,"所以，仓位管理，止损的目的，是让你在趋势的各个阶段，投入符合风险回报比的金额，就是盈亏比的由来。",-1),t("p",null,"那么，高手跟新手的根本区别在哪里？我觉得不是怎样用交易系统这个工具，而是判断哪里有趋势，高手的胜率更高。怎样成为高手呢？一种方式是成为你所要投资品种的专家，懂这个行业，懂这个品种，同时用系统管住自己的人性贪婪和恐惧。还有一种，财神加身，也就是运气爆表的人，在某一个品种的天使轮All In，赚够了身家后能激流勇退，离开赌场的人。",-1),t("p",null,"最终，我们作为凡人不要纠结于术，要重视道，交易的道是什么，不是赌博，是投资，你投资一个项目，花费的心血都是在盘外，多看书，多去产地走走，多跟产业的人聊聊。等你会用投资的心态，高度来看待交易的时候，你会发现期货交易，不过是一个自带杠杆的投资标的罢了，当你有更好的标的，胜率更高的投资项目可选的时，你缺的不过是资金杠杆，杠杆难么？",-1)]))}const m=l(o,[["render",s]]);export{i as __pageData,m as default};
